344		Let $\eps, \delta \ge 0$, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy that succeeds in the Magic Square game $\mathfrak{G}^{\mathrm{MS}}$ with probability at least $1-\eps$, where $\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$, and whose $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ measurements are consistent between the two players up to $\delta$ on $\ket{\psi}$, in the binary effects $\hat A$, $\hat B$ of Definition~\ref{def:ms-variable-agreement}:
345		\begin{equation}\label{eq:ms-rigidity-consistency}
346			\Delta_j(\mathcal S) = \sum_{b \in \F_2} \bigl\| \bigl( \hat A^{\mathsf{Variable}_j}_b \ot I_{\mathrm B} - I_{\mathrm A} \ot \hat B^{\mathsf{Variable}_j}_b \bigr) \ket{\psi} \bigr\|^2 \le \delta \qquad \text{for } j \in \{1, 5\}\,.
347		\end{equation}
348		This is the relation $\hat A^{\mathsf{Variable}_j}_b \ot I_{\mathrm B} \approx_\delta I_{\mathrm A} \ot \hat B^{\mathsf{Variable}_j}_b$ of Definition~\ref{def:povm-distance} with respect to $\ket{\psi}$, with constant $1$; for a symmetric strategy and $\delta = 0$ it says that the two binary measurements are consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement}, so every symmetric consistent strategy satisfies it with $\delta = 0$. Write $\eta = \sqrt\eps + \sqrt\delta$. Then there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot \hilb_{\mathrm B''}$, such that:
349		\begin{enumerate}
350			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\eta)$;
351			\item letting $\tilde A^{\mathsf{Variable}_j}_b = \phi_{\mathrm A} \hat A^{\mathsf{Variable}_j}_b \phi_{\mathrm A}^\dagger$ and $\tilde B^{\mathsf{Variable}_j}_b = \phi_{\mathrm B} \hat B^{\mathsf{Variable}_j}_b \phi_{\mathrm B}^\dagger$ denote the conjugated binary effects of Definition~\ref{def:ms-variable-agreement},
352			\begin{align*}
353				\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\eta} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
354				\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\eta} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
355				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\eta} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
356				I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\eta} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
357			\end{align*}
358			where each $\approx_{\eta}$ holds with respect to the extracted ideal state $\ket{\Theta} = \ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
359		\end{enumerate}
360		As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
361		\begin{align*}
362			\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\eta} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
363			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\eta} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
364		\end{align*}
365		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\zeta N$ means $\bra{\Theta} (M-N)^\dagger (M-N) \ket{\Theta} \le O(\zeta)$, evaluated on the extracted ideal state $\ket{\Theta}$ of item~2 --- the state on which the transported operators act --- and not on $\ket{\psi}$. For $\delta = 0$, in particular for every symmetric consistent strategy, the conclusion is the source's display, with $\eta = \sqrt\eps$.
